def first_waves(apps: Any, _schema_editor: Any) -> None:
    """Announcements published before waves existed get their first one in the history."""
    announcement_model = apps.get_model("announcements", "Announcement")
    wave_model = apps.get_model("announcements", "AnnouncementWave")
    for announcement in announcement_model.objects.filter(published_at__isnull=False):
        wave = wave_model.objects.create(
            id=uuid.uuid7(),
            announcement=announcement,
            number=1,
            reason="published",
            revision=1,
            started_by_id=announcement.reviewed_by_id,
        )
        wave_model.objects.filter(pk=wave.pk).update(created_at=announcement.published_at)


